// changing the result. Every pair collapses to 0 because x^x == 0, and
// 0^y == y leaves the lone element standing.

int hammingWeight(unsigned int n) {
    int count = 0;
    while (n) { n &= (n - 1); ++count; }   // each pass removes exactly one 1
    return count;
}
