bool isPowerOfTwo(int n) {
    return n > 0 && (n & (n - 1)) == 0;
}
// The n > 0 guard is LOAD-BEARING:
//   n == 0  ->  0 & -1 == 0, so without the guard it wrongly returns true.
//   n < 0   ->  e.g. INT_MIN is 1000...0, a single set bit, so it would also
//               wrongly return true even though it is not a power of two.

char findTheDifference(const string& s, const string& t) {
    int acc = 0;
    for (char c : s) acc ^= (unsigned char)c;
    for (char c : t) acc ^= (unsigned char)c;   // matched chars cancel across BOTH strings
    return (char)acc;
}

