int findComplement(int num) {
    // Build 000...0111...1 covering exactly the bits num actually uses.
    unsigned int mask = 0;
    while (mask < (unsigned int)num) mask = (mask << 1) | 1;
    if (num == 0) return 1;                 // 0 uses one bit; its complement is 1
    return (int)(num ^ mask);               // XOR with all-ones flips within the width
}
// 5 is 101. A naive ~5 gives ...11111010 (-6) because it flips the LEADING
// zeros too. Masking to width 3 gives 111, and 101 ^ 111 == 010 == 2. Correct.

