bool hasAlternatingBits(int n) {
    // If bits alternate, every adjacent pair differs, so XOR-ing with the
    // shifted value produces a run of ALL ones: 101 ^ 010 == 111.
    unsigned int x = (unsigned int)n ^ ((unsigned int)n >> 1);
    // A run of all ones is exactly one less than a power of two, so x+1 has a
    // single set bit -- which is the X203 test applied to x + 1.
    return (x & (x + 1)) == 0;
}

pair<int,int> twoOddOccurring(const vector<int>& a) {
    int mix = 0;
    for (int x : a) mix ^= x;              // mix == p ^ q, the two odd elements

    // p != q, so mix != 0 and has at least one set bit. Any such bit is a
    // position where p and q DIFFER -- take the lowest for simplicity.
    int bit = mix & (-mix);                // isolates the lowest set bit

    int p = 0, q = 0;
    for (int x : a) {
        if (x & bit) p ^= x;               // bucket where that bit is 1
        else         q ^= x;               // bucket where it is 0
    }
    return {p, q};
}

