def two_odd_occurring(a: list) -> tuple:
    mix = 0
    for x in a:
        mix ^= x                    # mix == p ^ q, the two odd-count elements

    # p != q, so mix != 0. Any set bit of mix is a position where they DIFFER.
    bit = mix & (-mix)              # isolates the lowest set bit

    p = q = 0
    for x in a:
        if x & bit:
            p ^= x                  # bucket where that bit is 1
        else:
            q ^= x                  # bucket where it is 0
    return (p, q) if p <= q else (q, p)

