// f(n) = XOR of 1..n. The pattern repeats every four numbers:
//   n % 4 == 0 -> n        (1^2^3 == 0, so a full block contributes nothing)
//   n % 4 == 1 -> 1
//   n % 4 == 2 -> n + 1
//   n % 4 == 3 -> 0
int xorUpTo(int n) {
    if (n < 0) return 0;
    switch (n % 4) {
        case 0: return n;
        case 1: return 1;
        case 2: return n + 1;
        default: return 0;
    }
}

// Range query: XOR over [l, r] is f(r) ^ f(l-1), since the shared prefix cancels.
int xorRange(int l, int r) { return xorUpTo(r) ^ xorUpTo(l - 1); }

solutionCode.py:
def xor_up_to(n: int) -> int:
    """XOR of 1..n. The pattern repeats every four numbers:
         n % 4 == 0 -> n        (a full block of four contributes nothing)
         n % 4 == 1 -> 1
         n % 4 == 2 -> n + 1
         n % 4 == 3 -> 0"""
    if n < 0:
        return 0
    r = n % 4
    if r == 0:
        return n
    if r == 1:
        return 1
    if r == 2:
        return n + 1
    return 0


def xor_range(l: int, r: int) -> int:
    """XOR over [l, r] is f(r) ^ f(l-1): the shared prefix cancels."""
    return xor_up_to(r) ^ xor_up_to(l - 1)

