vector<int> countBits(int n) {
    vector<int> bits(n + 1, 0);
    for (int i = 1; i <= n; ++i)
        bits[i] = bits[i >> 1] + (i & 1);   // i>>1 is already solved; add the lost bit
    return bits;
}
// WHY: dropping the last bit of i gives i >> 1, whose popcount is already known
// because i >> 1 < i. The only bit lost in the shift is i & 1. So the recurrence
// is exact and each entry costs O(1) -- this is dynamic programming in one line.
